package android.hardware.camera2;public class CameraDevice {public static final int TEMPLATE_RECORD=3;public abstract static class StateCallback{public abstract void onOpened(CameraDevice v);public abstract void onDisconnected(CameraDevice v);public abstract void onError(CameraDevice v,int c);public void onClosed(CameraDevice v){}}public StateCallback callback;public CameraCaptureSession session;public boolean closed;public int closeCalls;public boolean deferConfigure,failConfigure;public void close(){closeCalls++;closed=true;}public void completeDeviceClose(){callback.onClosed(this);}public CaptureRequest.Builder createCaptureRequest(int t){return new CaptureRequest.Builder();}public void createCaptureSession(android.hardware.camera2.params.SessionConfiguration c){session=new CameraCaptureSession(this);session.config=c;if(!deferConfigure)configure();}public void configure(){if(failConfigure){session.failed=true;session.config.executor.execute(()->session.config.callback.onConfigureFailed(session));}else{session.config.executor.execute(()->session.config.callback.onConfigured(session));}}}